-- =====================================================================
-- V3: 가격 제보 목데이터 + pharmacy_drug_price_stat 초기 계산
-- tools/seed-generator/build_price_seed.py 로 생성됨 (seed 고정, 재실행 가능)
-- =====================================================================






































-- pharmacy_drug_price_stat 초기 계산 (docs/DATABASE.md §5.2, docs/ROADMAP.md T-10과 동일 로직).
-- 1차: 최근 90일 창. 2차: 90일 창에 유효 제보가 없는 조합만 180일 창으로 확대.
WITH valid_90 AS (
    SELECT pharmacy_id, drug_id, price, purchased_at
    FROM price_report
    WHERE status = 'ACTIVE' AND flagged = false
      AND purchased_at >= CURRENT_DATE - 90
),
q_90 AS (
    SELECT *,
           percentile_cont(0.25) WITHIN GROUP (ORDER BY price) OVER (PARTITION BY pharmacy_id, drug_id) AS q1,
           percentile_cont(0.75) WITHIN GROUP (ORDER BY price) OVER (PARTITION BY pharmacy_id, drug_id) AS q3,
           count(*) OVER (PARTITION BY pharmacy_id, drug_id) AS n
    FROM valid_90
),
trimmed_90 AS (
    SELECT pharmacy_id, drug_id, price, purchased_at
    FROM q_90
    WHERE n < 4 OR price BETWEEN q1 - 1.5 * (q3 - q1) AND q3 + 1.5 * (q3 - q1)
)
SELECT
    t.pharmacy_id, t.drug_id,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY t.price)::int,
    MIN(t.price)::int, MAX(t.price)::int, AVG(t.price)::int, COUNT(*)::int,
    MAX(t.purchased_at), 90, now()
FROM trimmed_90 t
GROUP BY t.pharmacy_id, t.drug_id
ON CONFLICT (pharmacy_id, drug_id) DO NOTHING;

-- 2차: 90일 창에서 못 채운 조합을 180일 창으로 재시도
WITH covered AS (
    SELECT pharmacy_id, drug_id FROM pharmacy_drug_price_stat
),
valid_180 AS (
    SELECT pr.pharmacy_id, pr.drug_id, pr.price, pr.purchased_at
    FROM price_report pr
    WHERE pr.status = 'ACTIVE' AND pr.flagged = false
      AND pr.purchased_at >= CURRENT_DATE - 180
      AND NOT EXISTS (
          SELECT 1 FROM covered c
          WHERE c.pharmacy_id = pr.pharmacy_id AND c.drug_id = pr.drug_id
      )
),
q_180 AS (
    SELECT *,
           percentile_cont(0.25) WITHIN GROUP (ORDER BY price) OVER (PARTITION BY pharmacy_id, drug_id) AS q1,
           percentile_cont(0.75) WITHIN GROUP (ORDER BY price) OVER (PARTITION BY pharmacy_id, drug_id) AS q3,
           count(*) OVER (PARTITION BY pharmacy_id, drug_id) AS n
    FROM valid_180
),
trimmed_180 AS (
    SELECT pharmacy_id, drug_id, price, purchased_at
    FROM q_180
    WHERE n < 4 OR price BETWEEN q1 - 1.5 * (q3 - q1) AND q3 + 1.5 * (q3 - q1)
)
SELECT
    t.pharmacy_id, t.drug_id,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY t.price)::int,
    MIN(t.price)::int, MAX(t.price)::int, AVG(t.price)::int, COUNT(*)::int,
    MAX(t.purchased_at), 180, now()
FROM trimmed_180 t
GROUP BY t.pharmacy_id, t.drug_id
ON CONFLICT (pharmacy_id, drug_id) DO NOTHING;
